import{_ as o,o as d,c,a5 as n}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"构造函数绑定this对new的影响","description":"在 JavaScript 中，使用 bind 方法绑定一个构造函数并不会改变 this 在构造函数中的行为。这是因为当使用 new 关键字创建实例时， this 会指向新创建的对象，而不是绑定时传入的对象。 具体来说， bind 方法的优先级低于 new 操作符。当你使用 new。","frontmatter":{"title":"构造函数绑定this对new的影响","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"在 JavaScript 中，使用 bind 方法绑定一个构造函数并不会改变 this 在构造函数中的行为。这是因为当使用 new 关键字创建实例时， this 会指向新创建的对象，而不是绑定时传入的对象。 具体来说， bind 方法的优先级低于 new 操作符。当你使用 new。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/引用数据类型-函数/(20m)[重]this对象/构造函数绑定this对new的影响.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/构造函数绑定this对new的影响.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/构造函数绑定this对new的影响.md"}'),t={name:"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/构造函数绑定this对new的影响.md"};function i(s,e,a,r,l,p){return d(),c("div",null,[...e[0]||(e[0]=[n('<div><h1 id="构造函数绑定this对new的影响" tabindex="-1">构造函数绑定this对new的影响 <a class="header-anchor" href="#构造函数绑定this对new的影响" aria-label="Permalink to &quot;构造函数绑定this对new的影响&quot;">​</a></h1><blockquote><p>本节目标：理解“构造函数绑定this对new的影响”的核心思路，并能把它用于实际开发或面试表达。 在 JavaScript 中，使用 <code>bind</code> 方法绑定一个构造函数并不会改变 <code>this</code> 在构造函数中的行为。这是因为当使用 <code>new</code> 关键字创建实例时，<code>this</code> 会指向新创建的对象，而不是绑定时传入的对象。</p></blockquote><p>具体来说，<code>bind</code> 方法的优先级低于 <code>new</code> 操作符。当你使用 <code>new</code> 关键字调用一个被 <code>bind</code> 绑定过的构造函数时，<code>this</code> 会指向新创建的实例对象，而不是 <code>bind</code> 时指定的对象。</p><h3 id="示例代码" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码" aria-label="Permalink to &quot;示例代码&quot;">​</a></h3><p>function Person(name) { this.name = name; } let obj = { name: &#39;Bound Object&#39; }; let BoundPerson = Person.bind(obj); let person = new BoundPerson(&#39;Alice&#39;); console.log(person.name); // 输出: Alice console.log(person instanceof Person); // 输出: true console.log(person instanceof BoundPerson); // 输出: true console.log(obj.name); // 输出: Bound Object</p><p>在这个例子中，尽管 <code>Person</code> 构造函数通过 <code>bind</code> 方法绑定了 <code>obj</code> 对象，当我们用 <code>new BoundPerson(&#39;Alice&#39;)</code> 创建一个新实例时，<code>this</code> 指向的是新创建的实例对象 <code>person</code>，而不是 <code>obj</code> 对象。因此，<code>person.name</code> 输出的是 <code>&#39;Alice&#39;</code> 而不是 <code>&#39;Bound Object&#39;</code>。</p><h3 id="为什么-bind-不会影响-new-的行为" tabindex="-1">为什么 <code>bind</code> 不会影响 <code>new</code> 的行为？ <a class="header-anchor" href="#为什么-bind-不会影响-new-的行为" aria-label="Permalink to &quot;为什么 `bind` 不会影响 `new` 的行为？&quot;">​</a></h3><ul><li><p><strong><code>new</code> 操作符的行为</strong>：</p></li><li><p>创建一个新的空对象。</p></li><li><p>将这个新对象的 <code>__proto__</code> 指向构造函数的 <code>prototype</code>。</p></li><li><p>执行构造函数，并将构造函数内部的 <code>this</code> 绑定到这个新对象。</p></li><li><p>如果构造函数没有显式返回对象，则返回这个新对象。</p></li><li><p><strong><code>bind</code> 方法的行为</strong>：</p></li><li><p><code>bind</code> 方法创建一个新的函数，该函数的 <code>this</code> 永远指向传入的对象。</p></li><li><p>当这个新函数作为普通函数调用时，<code>this</code> 指向绑定的对象。</p></li><li><p>当这个新函数作为构造函数调用时，<code>this</code> 指向新创建的实例对象，而不是绑定的对象。</p></li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>使用 <code>bind</code> 绑定一个构造函数并不会影响用 <code>new</code> 创建实例时的 <code>this</code> 指向。<code>new</code> 关键字的优先级高于 <code>bind</code> 方法，它会确保 <code>this</code> 指向新创建的实例对象，而不是 <code>bind</code> 时传入的对象。这是因为构造函数调用和普通函数调用的机制不同，构造函数调用会自动绑定 <code>this</code> 到新创建的对象。</p></div>',1)])])}const _=o(t,[["render",i]]);export{b as __pageData,_ as default};
